from quick_lib import *

build("html", "HTML — Quick Revision", "Semantics, forms, accessibility and SEO in one sitting.", [
("must","easy","What is semantic HTML and why does it matter?",
 "Semantic elements describe the meaning of content (`header`, `nav`, `main`, `article`, `section`, `aside`, `footer`) instead of using generic `div`s. Benefits: accessibility (screen readers can navigate landmarks), SEO, and more readable code."),
("must","easy","Difference between block, inline and inline-block elements?",
 L("**Block** (`div`, `p`) starts on a new line and takes full width.","**Inline** (`span`, `a`) flows within text; width/height and vertical margins don't apply.","**Inline-block** flows inline but accepts width, height and margins.")),
("must","easy","What does the DOCTYPE do?",
 "`<!DOCTYPE html>` tells the browser to render in standards mode. Without it browsers fall back to quirks mode with legacy layout behaviour."),
("must","medium","`<script>` vs `async` vs `defer`?",
 L("Plain `<script>`: blocks HTML parsing while it downloads and runs.","`async`: downloads in parallel, runs as soon as ready (order not guaranteed).","`defer`: downloads in parallel, runs after parsing finishes, in order."),
 N("Use `defer` for scripts that depend on the DOM or on each other; `async` for independent scripts like analytics.")),
("must","medium","How do you make a page accessible?",
 L("Use semantic elements and a logical heading order.","Give every image meaningful `alt` text (empty `alt=\"\"` for decorative ones).","Associate every input with a `<label>`.","Make everything keyboard reachable with a visible focus style.","Use ARIA only when native HTML can't express the role; keep colour contrast sufficient.")),
("must","easy","What are `data-*` attributes?",
 "Custom attributes for storing extra information on an element, readable from JS through `element.dataset`.",
 C("html","<li data-id=\"42\" data-role=\"admin\">Sam</li>\n<script>\n  li.dataset.id; // \"42\"\n</script>")),
("must","easy","What is the difference between `<div>` and `<span>`?",
 "`div` is a block-level generic container for layout; `span` is an inline generic container for styling part of text. Neither carries meaning."),
("must","medium","How do HTML forms work? Name common input types and validation attributes.",
 "A `<form>` groups controls and submits their `name`/value pairs to its `action` using `method` GET or POST. Input types include `text, email, password, number, date, checkbox, radio, file, range, tel, url`. Built-in validation: `required, min, max, minlength, maxlength, pattern, type`."),
("good","medium","`localStorage` vs `sessionStorage` vs cookies?",
 L("**localStorage**: ~5 MB, persists until cleared, never sent to the server.","**sessionStorage**: same API, cleared when the tab closes.","**Cookies**: ~4 KB, sent with every request, can expire and be `HttpOnly`/`Secure`.")),
("good","easy","What are meta tags? Which ones matter most?",
 L("`<meta charset=\"utf-8\">` — character encoding.","`<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">` — responsive layout on mobile.","`description`, Open Graph (`og:title`, `og:image`) — search and social previews.")),
("good","medium","How do responsive images work (`srcset`, `sizes`, `picture`)?",
 "`srcset` + `sizes` let the browser pick the best file for the screen width and pixel density; `<picture>` with `<source>` swaps formats or art direction. Add `loading=\"lazy\"` for below-the-fold images and always set width/height to avoid layout shift.",
 C("html","<img src=\"a-800.jpg\" srcset=\"a-400.jpg 400w, a-800.jpg 800w\" sizes=\"(max-width: 600px) 100vw, 50vw\" alt=\"Team photo\" loading=\"lazy\">")),
("good","easy","`<b>` vs `<strong>` and `<i>` vs `<em>`?",
 "`strong` and `em` convey importance/emphasis (screen readers may change tone); `b` and `i` are purely stylistic."),
("good","medium","What is the difference between `id` and `class`?",
 "`id` must be unique per page and identifies one element (anchors, labels, JS hooks). `class` can be reused on many elements and combined. In CSS, id selectors have higher specificity."),
("good","medium","What do `<dialog>`, `<details>` and `<template>` do?",
 L("`<dialog>`: native modal/non-modal dialog (`showModal()`).","`<details>`/`<summary>`: built-in disclosure widget.","`<template>`: inert markup you clone with JS.")),
("good","hard","What happens when you type a URL and press Enter?",
 OL("DNS lookup resolves the domain to an IP.","TCP (and TLS) connection is established.","Browser sends the HTTP request; server responds with HTML.","The browser parses HTML into the DOM and CSS into the CSSOM, builds the render tree.","Layout, paint and composite; scripts and other resources load along the way.")),
])

build("css", "CSS — Quick Revision", "Layout, specificity and the box model — the CSS interview core.", [
("must","easy","Explain the CSS box model.",
 "Every element is a box: **content → padding → border → margin**. With `box-sizing: content-box` (default) `width` covers only the content; with `border-box` it includes padding and border, which is why most resets use `* { box-sizing: border-box }`."),
("must","medium","How is specificity calculated?",
 "Compare in order: inline style > IDs > classes/attributes/pseudo-classes > elements/pseudo-elements. `!important` overrides normal rules. With equal specificity the later rule wins.",
 C("css","p { }            /* 0,0,0,1 */\n.card p { }      /* 0,0,1,1 */\n#hero .card p { } /* 0,1,1,1 */")),
("must","medium","Flexbox: main axis vs cross axis, and the key properties?",
 L("`display:flex` on the container; `flex-direction` sets the main axis.","`justify-content` aligns along the main axis; `align-items` along the cross axis.","`flex-wrap`, `gap` for spacing and wrapping.","On items: `flex: grow shrink basis`, `align-self`, `order`.")),
("must","medium","Flexbox vs Grid — when do you use each?",
 "Flexbox is **one-dimensional** (a row or a column) — ideal for toolbars, nav and centring. Grid is **two-dimensional** (rows and columns together) — ideal for page layouts and card galleries.",
 C("css",".gallery {\n  display: grid;\n  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));\n  gap: 16px;\n}")),
("must","easy","How do you centre a div horizontally and vertically?",
 C("css",".parent {\n  display: grid;\n  place-items: center;\n}\n/* or: display:flex; justify-content:center; align-items:center; */")),
("must","medium","`position`: static, relative, absolute, fixed, sticky?",
 L("**static**: normal flow.","**relative**: offset from its normal spot; creates a positioning context.","**absolute**: removed from flow, positioned against the nearest positioned ancestor.","**fixed**: positioned against the viewport.","**sticky**: relative until a scroll threshold, then fixed.")),
("must","medium","What is the difference between `em`, `rem`, `%`, `vh/vw`?",
 L("`rem` — relative to the root font size (predictable scaling).","`em` — relative to the element's (or parent's) font size; compounds when nested.","`%` — relative to the parent's corresponding property.","`vw/vh` — 1% of viewport width/height.")),
("must","medium","How do you build a responsive layout?",
 "Start mobile-first with fluid units, flexible grids and `max-width`. Add `@media (min-width: …)` breakpoints, use `clamp()` for fluid type, and `<meta name=\"viewport\">`. Container queries let a component respond to its own container instead of the viewport."),
("good","medium","What is a stacking context and how does z-index work?",
 "`z-index` only orders elements within the same stacking context. A new context is created by the root, positioned elements with a z-index, `opacity < 1`, `transform`, `filter`, `isolation: isolate` and more. A child can never escape its parent's context."),
("good","medium","`display: none` vs `visibility: hidden` vs `opacity: 0`?",
 L("`display:none` — removed from layout and accessibility tree.","`visibility:hidden` — invisible but still occupies space.","`opacity:0` — invisible, occupies space and still receives events.")),
("good","medium","What are CSS custom properties (variables)?",
 "Defined with `--name` and read with `var(--name, fallback)`. They cascade and inherit, can change at runtime with JS, and make theming (e.g. dark mode) simple.",
 C("css",":root { --brand: #0d9488; }\n[data-theme='dark'] { --brand: #2dd4bf; }\n.btn { background: var(--brand); }")),
("good","medium","Pseudo-classes vs pseudo-elements?",
 "Pseudo-classes select an element in a state (`:hover`, `:focus-visible`, `:nth-child()`, `:not()`). Pseudo-elements style a part of it or generate content (`::before`, `::after`, `::placeholder`)."),
("good","medium","What is margin collapsing?",
 "Adjacent vertical margins of block elements (siblings, or parent and first/last child) combine into one — the larger wins. It doesn't happen in flex or grid containers, or when padding/border separates the margins."),
("good","medium","How do transitions and animations differ?",
 "A **transition** animates between two states when a property changes. A **@keyframes animation** can run on load, have many steps, loop and be controlled independently. Prefer animating `transform` and `opacity` for smooth, GPU-friendly results."),
("good","easy","What does `clamp()` give you?",
 "`clamp(min, preferred, max)` picks a value that grows with the viewport but is bounded, e.g. `font-size: clamp(1rem, 2vw + .5rem, 2rem)` — fluid typography without media queries."),
])

build("typescript", "TypeScript — Quick Revision", "Types, generics and utility types you are expected to know.", [
("must","easy","What is TypeScript and why use it?",
 "TypeScript is a typed superset of JavaScript that compiles to plain JS. Types are checked at compile time, catching bugs early, enabling autocomplete and safe refactoring. They are erased at runtime, so there is no runtime cost."),
("must","easy","`interface` vs `type` — what is the difference?",
 L("Both describe object shapes and can be extended.","`interface` supports declaration merging and `extends`; best for public object contracts and classes.","`type` can also name unions, tuples, primitives and mapped/conditional types.")),
("must","easy","`any` vs `unknown` vs `never`?",
 L("`any` turns off type checking — avoid.","`unknown` is the type-safe `any`: you must narrow it before use.","`never` is a value that can't exist (function that always throws, exhausted union)."),
 C("ts","function len(x: unknown) {\n  if (typeof x === 'string') return x.length; // narrowed\n  return 0;\n}")),
("must","medium","What are generics?",
 "Generics let a function, class or type work with many types while keeping them linked, instead of using `any`.",
 C("ts","function first<T>(items: T[]): T | undefined {\n  return items[0];\n}\nfirst([1, 2]);      // number | undefined\nfirst(['a']);       // string | undefined")),
("must","medium","What are union and intersection types?",
 L("`A | B` — a value is either A or B.","`A & B` — a value has all members of A and B."),
 C("ts","type Id = string | number;\ntype Admin = User & { permissions: string[] };")),
("must","medium","How does type narrowing work?",
 "TypeScript narrows a union inside a branch using `typeof`, `instanceof`, `in`, equality checks, truthiness, or a discriminant property. User-defined guards use `x is T`.",
 C("ts","type Shape = { kind: 'circle'; r: number } | { kind: 'square'; s: number };\nfunction area(sh: Shape) {\n  switch (sh.kind) {\n    case 'circle': return Math.PI * sh.r ** 2;\n    case 'square': return sh.s ** 2;\n  }\n}")),
("must","medium","Name the common utility types.",
 L("`Partial<T>` — all properties optional.","`Required<T>` — all required.","`Readonly<T>` — immutable properties.","`Pick<T, K>` / `Omit<T, K>` — choose or drop keys.","`Record<K, V>` — object with keys K and values V.","`ReturnType<F>`, `Parameters<F>`, `NonNullable<T>`.")),
("must","easy","Optional properties, `readonly`, and the non-null assertion?",
 L("`name?: string` — may be missing (`string | undefined`).","`readonly id: number` — can't be reassigned.","`value!` — tells the compiler it isn't null/undefined; unchecked, so use sparingly.")),
("good","medium","What is `enum` and what are alternatives?",
 "`enum` creates a named set of constants (numeric by default; string enums are safer). A lighter alternative is a union of literals — `type Role = 'admin' | 'user'` — which has no runtime code."),
("good","medium","What does `strict` mode enable?",
 "`strict: true` turns on a group of checks including `strictNullChecks`, `noImplicitAny`, `strictFunctionTypes` and `strictPropertyInitialization`. It's the recommended default for new projects."),
("good","hard","What are mapped and conditional types?",
 C("ts","type Flags<T> = { [K in keyof T]: boolean };       // mapped\ntype IsString<T> = T extends string ? 'yes' : 'no'; // conditional"),
 "Combined with `infer` they power utilities such as `ReturnType`."),
("good","medium","`keyof`, `typeof` and indexed access types?",
 C("ts","const user = { id: 1, name: 'Sam' };\ntype User = typeof user;      // { id: number; name: string }\ntype Key = keyof User;        // 'id' | 'name'\ntype Name = User['name'];     // string")),
("good","medium","How do you type React props and hooks?",
 C("tsx","type ButtonProps = { label: string; onClick?: () => void };\nconst Button = ({ label, onClick }: ButtonProps) => <button onClick={onClick}>{label}</button>;\n\nconst [user, setUser] = useState<User | null>(null);")),
("good","medium","`as` assertions vs type guards vs `satisfies`?",
 "`as` forces a type and can lie. A type guard proves it at runtime. `satisfies` checks that a value matches a type **without widening** its inferred type."),
("good","hard","What is structural typing?",
 "TypeScript compares types by shape, not by name. Any object with the required properties is assignable, even if it was never declared as that type."),
])

build("nodejs", "Node.js — Quick Revision", "The runtime concepts that come up in backend and full-stack interviews.", [
("must","easy","What is Node.js and why is it fast for I/O?",
 "Node.js is a JavaScript runtime built on Chrome's V8 engine. It uses a **single-threaded event loop** with non-blocking I/O (libuv), so one process can handle many concurrent connections while waiting on disk or network."),
("must","medium","Explain the Node.js event loop phases.",
 OL("**timers** — `setTimeout`/`setInterval` callbacks","**pending callbacks** — deferred system callbacks","**poll** — retrieve and run I/O callbacks","**check** — `setImmediate` callbacks","**close callbacks**"),
 "`process.nextTick` and promise microtasks run between phases, before the loop continues."),
("must","medium","`process.nextTick` vs `setImmediate` vs `setTimeout(0)`?",
 L("`nextTick` — runs right after the current operation, before other async work.","`setTimeout(0)` — timers phase, after at least ~1 ms.","`setImmediate` — check phase, after I/O callbacks.")),
("must","easy","CommonJS vs ES Modules?",
 L("CommonJS: `require()` / `module.exports`, synchronous loading.","ESM: `import` / `export`, static analysis and top-level `await`; enable with `\"type\": \"module\"` or `.mjs`.")),
("must","medium","How do callbacks, promises and async/await relate in Node?",
 "Callbacks (error-first `(err, data)`) came first and led to nesting. Promises flatten chains and `async/await` makes them read like sync code. `util.promisify` or `fs/promises` convert callback APIs.",
 C("js","import { readFile } from 'node:fs/promises';\nconst text = await readFile('data.json', 'utf8');")),
("must","medium","What is middleware in Express?",
 "A function `(req, res, next)` that runs between the request and the final handler — for logging, parsing bodies, authentication, validation, error handling. Order matters; call `next()` to continue or end the response.",
 C("js","app.use(express.json());\napp.use((req, res, next) => { console.log(req.method, req.url); next(); });\napp.get('/users', (req, res) => res.json([]));")),
("must","medium","How do you handle errors in Node/Express?",
 L("Use `try/catch` with `async/await` and pass errors to `next(err)`.","Register an error-handling middleware `(err, req, res, next)` last.","Listen for `unhandledRejection` / `uncaughtException` to log and exit cleanly.")),
("must","medium","What are streams and why use them?",
 "Streams process data in chunks instead of loading it all in memory — `Readable`, `Writable`, `Duplex`, `Transform`. They give low memory use and backpressure handling.",
 C("js","import { createReadStream, createWriteStream } from 'node:fs';\nimport { pipeline } from 'node:stream/promises';\nawait pipeline(createReadStream('in.txt'), createWriteStream('out.txt'));")),
("good","medium","What is the difference between `fork`, `spawn`, worker threads and cluster?",
 L("`child_process.spawn/fork` start separate OS processes.","`worker_threads` run JS on extra threads within one process — good for CPU-heavy work.","`cluster` forks one worker per CPU core sharing a server port.")),
("good","medium","How do you secure a Node API?",
 L("Validate and sanitise all input; use parameterised queries.","Hash passwords (bcrypt/argon2); use short-lived JWTs or sessions with `HttpOnly` cookies.","`helmet` headers, CORS allow-list, rate limiting.","Keep dependencies updated; never commit secrets — use environment variables.")),
("good","easy","What is `package.json` and the difference between dependencies and devDependencies?",
 "`package.json` describes the project: name, scripts, and dependencies. `dependencies` are needed at runtime; `devDependencies` only for development (tests, linters, build tools). `package-lock.json` pins exact versions."),
("good","medium","What is a Buffer?",
 "A fixed-size chunk of raw binary memory outside the V8 heap, used for files, network packets and encodings.",
 C("js","const buf = Buffer.from('hi', 'utf8');\nbuf.toString('hex'); // '6869'")),
("good","medium","What is the difference between REST and GraphQL?",
 "REST exposes multiple resource endpoints with fixed responses. GraphQL exposes one endpoint where the client specifies exactly the fields it needs, reducing over- and under-fetching at the cost of more server complexity."),
("good","medium","How do you scale a Node.js application?",
 L("Run multiple processes (cluster/PM2) or containers behind a load balancer.","Keep the app stateless; move sessions to Redis.","Cache hot data, use queues for slow jobs, offload CPU work to worker threads.")),
("good","easy","What does `EventEmitter` do?",
 "Core class for the publish/subscribe pattern: `on(event, fn)` registers a listener and `emit(event, data)` calls them. Many Node APIs (streams, HTTP servers) are built on it.",
 C("js","import { EventEmitter } from 'node:events';\nconst bus = new EventEmitter();\nbus.on('ready', (n) => console.log(n));\nbus.emit('ready', 1);")),
])
